            window.Navigate(book.Id,id);editor=await window.ReadyEditor();var fromNavigation=new Note{NotebookId=book.Id,Title="清空入口测试",DeletedAt=Clock.Now};vm.Change(w=>w with{Notes=[..w.Notes,fromNavigation]},"edit");var trashNavigationMenu=window.BuildTrashNavigationMenu();var clearFromNav=(MenuItem)trashNavigationMenu.Items[0];if(!clearFromNav.IsEnabled||clearFromNav.Header?.ToString()!="清空回收站")throw new Exception("Inactive trash navigation has no clear action");_=Application.Current.Dispatcher.BeginInvoke(new Action(()=>{var dialog=Application.Current.Windows.OfType<Window>().First(w=>w.Owner==window);FindButton(dialog,"清空回收站")!.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}),DispatcherPriority.ContextIdle);clearFromNav.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));await Render();if(vm.View!=book.Id||vm.SelectedId!=id||vm.State.Notes.First(n=>n.Id==fromNavigation.Id).PurgedAt==null||((MenuItem)window.BuildTrashNavigationMenu().Items[0]).IsEnabled)throw new Exception("Trash navigation clear changed the current page or failed to disable when empty");checks.Add("right-click trash navigation clears with confirmation from another page and disables when empty without navigating");
            Application.Current.ShutdownMode=ShutdownMode.OnExplicitShutdown;await editor.Flush();await vm.SaveAsync();window.Close();await Render();checks.Add("closing waits for the shared editor bridge and local save");
            if(Environment.GetEnvironmentVariable("MOJI_FORCE_WEBVIEW_BOOTSTRAP")=="1"&&EditorFiles.BootstrapperInvocations!=1)throw new Exception("Reopening editors must reuse the shared Evergreen runtime");
            await File.WriteAllTextAsync(Path.Combine(output,"report.json"),Json.Serialize(new{success=true,framework="WPF / WebView2 / Tiptap 3.34.0 official Simple Editor",embeddedBrowser=true,editorReadyMilliseconds,bootstrapperInvocations=EditorFiles.BootstrapperInvocations,hasFixedRuntime=EditorFiles.HasFixedRuntime,sharedRuntime=CoreWebView2Environment.GetAvailableBrowserVersionString(),checks}));Application.Current.Shutdown(0);
        } catch(Exception e){await File.WriteAllTextAsync(Path.Combine(output,"report.json"),Json.Serialize(new{success=false,error=e.ToString(),checks}));Application.Current.Shutdown(1);}
    }
    private static bool SelectedGlyphsVisible(Window window,TextBox box)
    {
        var root=(FrameworkElement)window.Content;var first=box.GetRectFromCharacterIndex(0);var last=box.GetRectFromCharacterIndex(box.Text.Length-1,true);first.Union(last);var at=box.TranslatePoint(first.TopLeft,root);var crop=new Int32Rect(Math.Max(0,(int)at.X),Math.Max(0,(int)at.Y),Math.Max(1,(int)Math.Ceiling(first.Width)),Math.Max(1,(int)Math.Ceiling(first.Height)));var image=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);image.Render(root);var pixels=new byte[crop.Width*crop.Height*4];image.CopyPixels(crop,pixels,crop.Width*4,0);var ink=0;for(var i=0;i<pixels.Length;i+=4)if(pixels[i]<120&&pixels[i+1]<110&&pixels[i+2]<100&&pixels[i+3]>200)ink++;return ink>=box.Text.Length;
    }
    private static async Task Script(SharedEditorView editor,string code){await editor.Browser.CoreWebView2.ExecuteScriptAsync("(()=>{"+code+"})()");await Render();}
    private static async Task Render(){await Application.Current.Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);await Task.Delay(300);}
    private static void Capture(Window window,string path)=>CaptureElement((FrameworkElement)window.Content,path);
    private static void CaptureElement(FrameworkElement root,string path){var bitmap=new RenderTargetBitmap(Math.Max(1,(int)root.ActualWidth),Math.Max(1,(int)root.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var stream=File.Create(path);encoder.Save(stream);}
    private static T? Ancestor<T>(DependencyObject? root)where T:DependencyObject{for(var parent=root==null?null:VisualTreeHelper.GetParent(root);parent!=null;parent=VisualTreeHelper.GetParent(parent))if(parent is T match)return match;return null;}
    private static IEnumerable<T> FindAll<T>(DependencyObject root)where T:DependencyObject {if(root is T value)yield return value;for(var i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var found in FindAll<T>(VisualTreeHelper.GetChild(root,i)))yield return found;}
    private static T? FindNamed<T>(DependencyObject root,string name)where T:FrameworkElement{if(root is T t&&t.Name==name)return t;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=FindNamed<T>(VisualTreeHelper.GetChild(root,i),name);if(found!=null)return found;}return null;}
    private static Button? FindButton(DependencyObject root,string label){if(root is Button{Content:string value} button&&value==label)return button;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=FindButton(VisualTreeHelper.GetChild(root,i),label);if(found!=null)return found;}return null;}
    private static bool HasButton(DependencyObject root,string label){if(root is Button{Content:string value}&&value==label)return true;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)if(HasButton(VisualTreeHelper.GetChild(root,i),label))return true;return false;}
